{
  "name": "@thd3178/opencode-poorguy-shellkeeper",
  "version": "0.1.1",
  "description": "Persistent PowerShell sessions for opencode, plus a live TUI sidebar panel",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "powershell",
    "persistent-shell",
    "tui"
  ],
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "bun build src/index.ts src/tui.tsx --outdir dist --target node --format esm --external @opencode-ai/plugin --external @opencode-ai/sdk --external @opencode-ai/plugin/tui --external @opentui/core --external @opentui/solid --external solid-js && tsc -p tsconfig.build.json",
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "publishConfig": {
    "access": "public"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@opentui/solid": "latest",
    "@types/node": "^22.0.0",
    "bun-types": "latest",
    "solid-js": "1.9.12",
    "typescript": "^5.9.0"
  }
}
